import fs from "node:fs";
import path from "node:path";

const target = process.argv[2] || "docs/assets/images";
fs.mkdirSync(target,{recursive:true});

const assets = {
"hero-desktop.webp": "",
"hero-mobile.webp": "",
"office-profile.webp": "",
"office-gallery-1.webp": "",
"office-gallery-2.webp": "",
"contact-profile.webp": "",
"brand-symbol.webp": "",
};

for (const [name,data] of Object.entries(assets)) {
  fs.writeFileSync(path.join(target,name), Buffer.from(data,"base64"));
}
console.log(`Generated ${Object.keys(assets).length} image assets in ${target}`);